// @generated by:gauntlet run:pattern-version-hypotheses
mod common;

use anatoly::{fingerprints::Catalog, scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::{Value, json};
use std::sync::Arc;

fn settings() -> ScanOptions {
    let mut options = ScanOptions {
        samples: 1,
        discover: false,
        ..ScanOptions::default()
    };
    options.network.no_proxy = true;
    options
}

fn inspect(path: &str, headers: &str, body: &str, options: ScanOptions) -> Value {
    let headers = headers.to_owned();
    let body = body.to_owned();
    let server = Server::new(move |_| response("200 OK", &headers, &body));
    let report = serde_json::to_value(
        scan_configured(&format!("{}{path}", server.url), limits(), &options).unwrap(),
    )
    .unwrap();
    assert_eq!(server.paths.lock().unwrap().len(), options.samples);
    report
}

fn proposals(report: &Value) -> &[Value] {
    report["version_hypotheses"]
        .as_array()
        .expect("structured hypotheses must be serialized")
}

fn proposal<'a>(report: &'a Value, technology: &str, range: &str) -> &'a Value {
    proposals(report)
        .iter()
        .find(|p| p["technology"] == technology && p["range"] == range)
        .unwrap_or_else(|| panic!("missing {technology} {range}: {report}"))
}

fn assert_no_exact_php(report: &Value) {
    assert!(report["version"].is_null());
    assert_eq!(report["version_status"], "unknown");
    assert_eq!(report["version_candidates"], json!([]));
    assert_eq!(report["verdict"], "inconclusive");
}

fn pack(rules: Value) -> Value {
    json!({"schema_version":1,"technologies":[{"name":"Acme Framework","kind":"framework",
        "runtime":"PHP","rules":rules}]})
}

fn hint(range: &str) -> Value {
    json!({"range":range,"confidence":"low","reason":"Conditional signature compatibility",
        "reference":"https://example.com/reference"})
}

fn with_pack(document: Value) -> ScanOptions {
    let mut options = settings();
    options.fingerprints = Some(Arc::new(
        Catalog::with_extra_json(&document.to_string()).unwrap(),
    ));
    options
}

#[test]
fn modern_laravel_cookie_produces_conditional_ranges_without_inventing_exact_versions() {
    let report = inspect(
        "",
        "Set-Cookie: laravel-session=PRIVATE_COOKIE_FIXTURE; Path=/\r\n",
        "application",
        settings(),
    );
    for (technology, range) in [("Laravel", ">=12"), ("PHP", ">=8.2")] {
        let candidate = proposal(&report, technology, range);
        assert_eq!(candidate["confidence"], "low");
        assert!(!candidate["basis"].as_str().unwrap().is_empty());
        assert!(!candidate["sources"].as_array().unwrap().is_empty());
        assert!(!candidate["references"].as_array().unwrap().is_empty());
        assert!(!candidate["limitations"].as_array().unwrap().is_empty());
    }
    let framework = report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|t| t["name"] == "Laravel")
        .unwrap();
    assert_eq!(framework["versions"], json!([]));
    assert!(!report.to_string().contains("PRIVATE_COOKIE_FIXTURE"));
    assert_no_exact_php(&report);
}

#[test]
fn old_or_lookalike_cookie_names_do_not_predict_modern_laravel_versions() {
    for cookie in [
        "laravel_session",
        "laravel-sessionish",
        "my-laravel-session",
    ] {
        let report = inspect(
            "",
            &format!("Set-Cookie: {cookie}=PRIVATE_COOKIE_FIXTURE\r\n"),
            "application",
            settings(),
        );
        assert!(
            !proposals(&report)
                .iter()
                .any(|p| p["technology"] == "Laravel" && p["range"] == ">=12")
        );
        assert_no_exact_php(&report);
    }
}

#[test]
fn suppression_flags_remove_hypotheses_and_cookie_based_predictions() {
    for no_cookie_hints in [false, true] {
        let mut options = settings();
        options.no_cookie_hints = no_cookie_hints;
        options.no_hypotheses = !no_cookie_hints;
        let report = inspect(
            "",
            "Set-Cookie: laravel-session=PRIVATE_COOKIE_FIXTURE\r\n",
            "application",
            options,
        );
        assert!(proposals(&report).is_empty());
        if !no_cookie_hints {
            assert!(
                report["technologies"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|t| t["name"] == "Laravel")
            );
        }
    }
}

#[test]
fn exact_framework_versions_supersede_its_pattern_guess_without_becoming_php_versions() {
    let report = inspect(
        "",
        "X-Powered-By: Laravel/12.70.2\r\nSet-Cookie: laravel-session=PRIVATE_COOKIE_FIXTURE\r\n",
        "application",
        settings(),
    );
    assert!(
        !proposals(&report)
            .iter()
            .any(|p| p["technology"] == "Laravel")
    );
    proposal(&report, "PHP", ">=8.2");
    assert_no_exact_php(&report);
}

#[test]
fn exact_php_evidence_suppresses_runtime_guesses_and_keeps_the_real_cve_verdict() {
    let report = inspect(
        "",
        "X-Powered-By: PHP/8.4.26\r\nSet-Cookie: laravel-session=PRIVATE_COOKIE_FIXTURE\r\n",
        "application",
        settings(),
    );
    assert!(!proposals(&report).iter().any(|p| p["technology"] == "PHP"));
    assert_eq!(report["version"]["patch"], 26);
    assert_eq!(report["verdict"], "potentially_affected");
}

#[test]
fn partial_headers_and_php_error_patterns_keep_supported_ranges_distinct_from_proof() {
    let partial = inspect("", "X-Powered-By: PHP/8.4\r\n", "application", settings());
    assert_eq!(proposal(&partial, "PHP", "8.4.x")["confidence"], "medium");
    assert_no_exact_php(&partial);
    let behavior = inspect(
        "",
        "",
        "Deprecated: Creation of dynamic property Example::$value is deprecated",
        settings(),
    );
    assert_eq!(proposal(&behavior, "PHP", ">=8.2,<9")["confidence"], "low");
    assert_no_exact_php(&behavior);
}

#[test]
fn composer_platform_constraints_remain_conditional_runtime_hypotheses() {
    let report = inspect(
        "composer.json",
        "",
        r#"{"require":{"php":"^8.2"}}"#,
        settings(),
    );
    assert_eq!(proposal(&report, "PHP", "^8.2")["confidence"], "low");
    assert_no_exact_php(&report);
}

#[test]
fn wordpress_asset_versions_predict_only_the_component_that_owns_the_cache_hint() {
    let report = inspect(
        "",
        "",
        "<script src='/wp-content/plugins/custom-calendar/main.js?ver=2.4.1&amp;private=PRIVATE_QUERY_FIXTURE'></script>",
        settings(),
    );
    assert_eq!(
        proposal(&report, "WordPress plugin:custom-calendar", "=2.4.1")["confidence"],
        "low"
    );
    assert!(
        !proposals(&report)
            .iter()
            .any(|p| p["technology"] == "WordPress" || p["technology"] == "PHP")
    );
    assert!(!report.to_string().contains("PRIVATE_QUERY_FIXTURE"));
    assert_no_exact_php(&report);
}

#[test]
fn custom_header_html_asset_and_cookie_signatures_generate_only_qualified_guesses() {
    let fixtures = [
        (
            json!({"channel":"header","key":"x-acme-pattern","pattern":"^modern$","hypothesis":hint(">=3,<5")}),
            "X-Acme-Pattern: modern\r\n",
            "application",
        ),
        (
            json!({"channel":"html","selector":"meta[name=acme-pattern]","attribute":"content","pattern":"^modern$","hypothesis":hint(">=3,<5")}),
            "",
            "<meta name=acme-pattern content=modern>",
        ),
        (
            json!({"channel":"asset","pattern":"/acme-modern.js$","hypothesis":hint(">=3,<5")}),
            "",
            "<script src='/acme-modern.js'></script>",
        ),
        (
            json!({"channel":"cookie","pattern":"^acme_modern$","hypothesis":hint(">=3,<5")}),
            "Set-Cookie: acme_modern=PRIVATE_COOKIE_FIXTURE\r\n",
            "application",
        ),
    ];
    for (rule, headers, body) in fixtures {
        let report = inspect("", headers, body, with_pack(pack(json!([rule]))));
        assert_eq!(
            proposal(&report, "Acme Framework", ">=3,<5")["confidence"],
            "low"
        );
        let framework = report["technologies"]
            .as_array()
            .unwrap()
            .iter()
            .find(|t| t["name"] == "Acme Framework")
            .unwrap();
        assert_eq!(framework["versions"], json!([]));
        assert!(!report.to_string().contains("PRIVATE_COOKIE_FIXTURE"));
        assert_no_exact_php(&report);
    }
}

#[test]
fn repeated_signatures_do_not_inflate_confidence_or_duplicate_proposal_sources() {
    let document = pack(
        json!([{"channel":"header","key":"x-acme-pattern","pattern":"^modern$","hypothesis":hint(">=3,<5")} ]),
    );
    let mut options = with_pack(document);
    options.samples = 3;
    let report = inspect("", "X-Acme-Pattern: modern\r\n", "application", options);
    let candidates: Vec<_> = proposals(&report)
        .iter()
        .filter(|p| p["technology"] == "Acme Framework")
        .collect();
    assert_eq!(candidates.len(), 1);
    assert_eq!(candidates[0]["confidence"], "low");
    assert_eq!(candidates[0]["sources"].as_array().unwrap().len(), 1);
}

#[test]
fn incompatible_pattern_ranges_remain_alternatives_without_silent_intersection() {
    let document = pack(json!([
        {"channel":"header","key":"x-acme-pattern","pattern":"^modern$","hypothesis":hint(">=1,<3")},
        {"channel":"header","key":"x-acme-pattern","pattern":"^modern$","hypothesis":hint(">=4,<6")}
    ]));
    let report = inspect(
        "",
        "X-Acme-Pattern: modern\r\n",
        "application",
        with_pack(document),
    );
    proposal(&report, "Acme Framework", ">=1,<3");
    proposal(&report, "Acme Framework", ">=4,<6");
    assert_no_exact_php(&report);
}

#[test]
fn malformed_or_sensitive_hypothesis_metadata_is_rejected_before_scanning() {
    let mut bad_hints = vec![
        hint("arbitrary-version-text"),
        hint(">=1,\n<3"),
        hint(">=1,<3"),
    ];
    bad_hints[2]["reference"] = json!("https://user:private@example.com/reference");
    let mut query_reference = hint(">=1,<3");
    query_reference["reference"] = json!("https://example.com/reference?key=PRIVATE_QUERY_FIXTURE");
    bad_hints.push(query_reference);
    let mut oversized = hint(">=1,<3");
    oversized["reason"] = json!("x".repeat(2000));
    bad_hints.push(oversized);
    let mut unsupported_confidence = hint(">=1,<3");
    unsupported_confidence["confidence"] = json!("high");
    bad_hints.push(unsupported_confidence);
    for hypothesis in bad_hints {
        let document = pack(
            json!([{"channel":"header","key":"x-acme-pattern","pattern":"^modern$","hypothesis":hypothesis}]),
        );
        assert!(Catalog::with_extra_json(&document.to_string()).is_err());
    }
    let mixed = pack(
        json!([{"channel":"header","key":"x-acme-pattern","pattern":"^([0-9]+)$","version_group":1,"hypothesis":hint(">=1,<3")} ]),
    );
    assert!(Catalog::with_extra_json(&mixed.to_string()).is_err());
}

#[test]
fn proposal_count_is_bounded_even_for_many_matching_rules() {
    let rules: Vec<_> = (1..=70)
        .map(|n| {
            json!({"channel":"header","key":"x-acme-pattern","pattern":"^modern$",
        "hypothesis":hint(&format!(">={n},<{}", n + 1))})
        })
        .collect();
    let report = inspect(
        "",
        "X-Acme-Pattern: modern\r\n",
        "application",
        with_pack(pack(json!(rules))),
    );
    assert!(proposals(&report).len() <= 64);
    assert!(!proposals(&report).is_empty());
    assert_no_exact_php(&report);
}
